traps.trap01.txt:
// 切换到map099洞庭湖畔

	If ($Event == 610) @Event610;
	Return;
	
@Event610:	
	DisableNpcAI();
	SetNpcKind("杨瑛", 1);
	SetNpcDir("杨瑛", 3);
	SetPlayerDir(3);
	SetNpcActionFile("独孤剑", 0, "");
	SetNpcActionFile("独孤剑", 1, "");
	NpcSpecialAction("独孤剑", "mpc042.asf");
	SetNpcActionFile("杨瑛", 0, "");
	SetNpcActionFile("杨瑛", 1, "");
	NpcSpecialAction("杨瑛", "mpc049.asf");
	Sleep(1500);
	SetNpcKind("杨瑛", 3);
	FadeOut();
	SaveNpc();
	ClearBody();
	SaveObj();
	LoadMap("map099_洞庭湖畔.map");
	LoadNpc("map099.npc");
	LoadObj("map099.obj");
	StopMusic();
	PlayMusic("长路.mp3");
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	SetNpcActionFile("杨瑛", 0, "npc008_st.asf");
	SetNpcActionFile("杨瑛", 1, "npc008_pst.asf");
	SetPlayerPos(5, 18);
	SetPlayerDir(5);
	SetNpcPos("杨瑛", 5, 17);
	SetNpcDir("杨瑛", 1);
	CloseWaterEffect();
	ChangeMapColor(255, 255, 255);
	ChangeAsfColor(255, 255, 255);
	EnableNpcAI();
	FadeIn();
	Say("杨瑛：好痛快！想不到湖底竟有这么美！独孤大哥，我很久没有这么开心过了！", 39);
	SetNpcKind("杨瑛", 3);
	SetNpcRelation("杨瑛", 0);
	SetNpcScript("杨瑛", "杨瑛的同伴对话.txt");
	Return;

